    public void navigate(String route){if(!commitPending())return;pending=()->true;switch(route){case "home"->showHome();case "wizard"->showWizard();case "profiles"->showProfiles();case "presets"->showPresets();case "export"->showExport();case "server"->showServer();case "about"->showAbout();default->showEditor(route);}}
