        JComboBox<String> categoryChoice=new JComboBox<>(names);categoryChoice.setSelectedIndex(selectedCategory);categoryChoice.setMaximumSize(new Dimension(Integer.MAX_VALUE,px(44)));categoryChoice.addActionListener(e->{int index=categoryChoice.getSelectedIndex();navigate(index==0?"all":catalog.categories.get(index-1).id());});controls.add(categoryChoice);gap(controls,16);controls.add(label("ANZEIGE",10,MUTED));gap(controls,8);
