    private void readPrefs(){try{Path file=store.root.resolve("app.json");if(!Files.exists(file))return;Map<String,Object> p=Json.object(Json.parse(Workspace.read(file)));if(p.get("scale") instanceof BigDecimal n)scale=Math.max(.9f,Math.min(1.25f,n.floatValue()));if(p.get("updateMode") instanceof String s)updateMode=StartupUpdates.Mode.valueOf(s);if(p.get("favorites") instanceof List<?> list)for(Object o:list)if(o instanceof String s)favorites.add(s);}catch(Exception ex){status.setText("App-Einstellungen beschädigt; sichere Standardwerte werden verwendet.");}}
    private void writePrefs(){try{Workspace.atomic(store.root.resolve("app.json"),Json.write(Map.of("scale",new BigDecimal(Float.toString(requestedScale)),"updateMode",updateMode.name(),"favorites",new ArrayList<>(favorites))));}catch(Exception ex){fail(ex);}}
